1	import assert from 'node:assert/strict';
2	import { spawnSync } from 'node:child_process';
3	import fs from 'node:fs';
4	import os from 'node:os';
5	import path from 'node:path';
6	import { fileURLToPath } from 'node:url';
7	import { after } from 'node:test';
8	
9	export const CLI = fileURLToPath(new URL('../jsonpatch-cli.mjs', import.meta.url));
10	export const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
11	export const LIMIT = 1048576;
12	export const BOM = Buffer.from([0xef, 0xbb, 0xbf]);
13	
14	export function run(args, { input, stdinFd, cwd } = {}) {
15	  const opts = {
16	    cwd,
17	    maxBuffer: 64 * 1024 * 1024,
18	    encoding: 'utf8',
19	  };
20	  if (stdinFd !== undefined) {
21	    opts.stdio = [stdinFd, 'pipe', 'pipe'];
22	  } else {
23	    opts.input = input === undefined ? '' : input;
24	  }
25	  const r = spawnSync(process.execPath, [CLI, ...args], opts);
26	  return { status: r.status, stdout: r.stdout, stderr: r.stderr };
27	}
28	
29	// Creates a temp dir and registers cleanup for the calling suite.
30	export function tempDir() {
31	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'jsonpatch-cli-'));
32	  after(() => {
33	    fs.rmSync(dir, { recursive: true, force: true });
34	  });
35	  return dir;
36	}
37	
38	export function writeFile(dir, name, content) {
39	  const p = path.join(dir, name);
40	  fs.writeFileSync(p, content);
41	  return p;
42	}
43	
44	export function assertFailure(r, exitCode, line) {
45	  assert.equal(r.status, exitCode);
46	  assert.equal(r.stdout, '');
47	  assert.equal(r.stderr, line + '\n');
48	}
49	
50	export function assertSuccess(r, value) {
51	  assert.equal(r.status, 0);
52	  assert.equal(r.stderr, '');
53	  assert.equal(r.stdout, JSON.stringify(value, null, 2) + '\n');
54	}
55	
56	// Valid JSON '[]' padded with trailing spaces so that prefix + content is `total` bytes.
57	export function padded(total, prefix = Buffer.alloc(0)) {
58	  const body = Buffer.from('[]');
59	  const fill = Buffer.alloc(total - prefix.length - body.length, 0x20);
60	  return Buffer.concat([prefix, body, fill]);
61	}
