30	// Async run. With stdinOpen the stdin pipe is never written or ended, so a CLI that
31	// reads stdin too early hangs until timeoutMs, then is killed and timedOut is true.
32	export function runAsync(args, { stdinOpen = false, timeoutMs = 10000 } = {}) {
33	  return new Promise((resolve, reject) => {
34	    const child = spawn(process.execPath, [CLI, ...args], { stdio: ['pipe', 'pipe', 'pipe'] });
35	    let stdout = '';
36	    let stderr = '';
37	    let timedOut = false;
38	    child.stdout.setEncoding('utf8').on('data', (c) => { stdout += c; });
39	    child.stderr.setEncoding('utf8').on('data', (c) => { stderr += c; });
40	    const timer = setTimeout(() => {
41	      timedOut = true;
42	      child.kill('SIGKILL');
43	    }, timeoutMs);
44	    child.on('error', (err) => {
45	      clearTimeout(timer);
46	      reject(err);
47	    });
48	    child.on('close', (status) => {
49	      clearTimeout(timer);
50	      resolve({ status, stdout, stderr, timedOut });
51	    });
52	    if (!stdinOpen) child.stdin.end();
53	    else child.stdin.on('error', () => {});
54	  });
55	}
